async function listDesignations() {
	const departments = (await apiRequest("/api/v1/departments")).data || [];
	const designations = [];
	for (const dept of departments) if (dept.designations && Array.isArray(dept.designations)) for (const d of dept.designations) designations.push({
		...d,
		department_name: dept.name,
		department_id: dept.id
	});
	return designations;
}
